import glob,sys
def parse(fn):
    d=open(fn,'rb').read()
    i=2
    out=[]
    while i<len(d)-1:
        if d[i]!=0xff: 
            out.append(('??',i)); break
        m=d[i+1]
        if m in (0xd8,0xd9,0x01) or 0xd0<=m<=0xd7:
            i+=2; continue
        ln=(d[i+2]<<8)|d[i+3]
        out.append((hex(m),ln))
        if m==0xda:
            break
        i+=2+ln
    return out
for fn in sorted(glob.glob('assets/*.jpg')):
    print(fn, parse(fn))
EOF"}

