{"command": "cd /workspace && python3 - <<'EOF'
import glob
def markers(fn):
    d=open(fn,'rb').read()
    i=2; out=[]
    while i<len(d)-1:
        if d[i]!=0xff: break
        m=d[i+1]
        if m in (0xd8,0xd9,0x01) or 0xd0<=m<=0xd7:
            i+=2; continue
        ln=(d[i+2]<<8)|d[i+3]
        seg=d[i+4:i+2+ln]
        out.append((hex(m),ln,seg[:20]))
        if m==0xda: break
        i+=2+ln
    return out
for fn in sorted(glob.glob('assets/*.jpg')):
    ms=markers(fn)
    print("==",fn)
    for m,l,s in ms:
        if m in ('0xc0','0xc1','0xc2','0xdb','0xc4','0xdd','0xda'):
            print("  ",m,l,s.hex())
EOF"}

